head.b:skin:
:root {
    --main-bg: #050b14;
    --accent-color: #64ffda;
    --glass-bg: rgba(255, 255, 255, 0.05);
    --glass-border: rgba(255, 255, 255, 0.1);
    --text-primary: #e6f1ff;
    --text-secondary: #8892b0;
}

@keyframes bgMotion {
    0% { background-position: 0% 0%, 0% 0%; }
    50% { background-position: 100% 100%, 50px 50px; }
    100% { background-position: 0% 0%, 0% 0%; }
}

body {
    background-color: var(--main-bg);
    background-image: radial-gradient(circle at 50% 50%, rgba(10, 25, 47, 0.9), var(--main-bg)), url('https://www.transparenttextures.com/patterns/stardust.png');
    background-attachment: fixed;
    background-size: 200% 200%, auto;
    animation: bgMotion 20s infinite alternate ease-in-out;
    color: var(--text-primary);
    font-family: 'Inter', sans-serif;
    margin: 0; padding: 0;
    overflow-x: hidden;
}

header {
    background: rgba(10, 25, 47, 0.8); backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--glass-border); padding: 15px 0; position: fixed; width: 100%; top: 0; z-index: 1000;
}

.header-inner { width: 90%; max-width: 1200px; margin: 0 auto; display: flex; justify-content: space-between; align-items: center; }
.logo { font-size: 1.5rem; font-weight: 800; color: var(--accent-color); text-decoration: none; }

.main-container { max-width: 1200px; width: 92%; margin: 120px auto 60px; }

.page-nav-wrapper { margin-bottom: 40px; text-align: center; }
.PageList ul {
    list-style: none !important;
    padding: 0 !important;
    display: flex !important;
    justify-content: center !important;
    gap: 10px !important;
    flex-wrap: wrap !important;
    margin: 0 auto !important;
}
.PageList li a {
    background: var(--glass-bg) !important;
    border: 1px solid var(--glass-border) !important;
    color: var(--text-primary) !important;
    padding: 8px 16px !important;
    border-radius: 10px !important;
    text-decoration: none !important;
    font-weight: 600 !important;
    transition: 0.3s;
    display: inline-block !important;
    font-size: 0.85rem !important;
}

.posts-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 20px;
}

.post-card {
    background: var(--glass-bg);
    backdrop-filter: blur(15px);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    overflow: hidden;
    transition: 0.3s ease;
    text-decoration: none !important;
    display: flex;
    flex-direction: column;
    height: 100%;
}

.card-image-wrapper {
    width: 100%;
    height: 180px;
    overflow: hidden;
    background: rgba(255,255,255,0.02);
    display: flex;
    align-items: center;
    justify-content: center;
    border-bottom: 1px solid var(--glass-border);
}
.card-image-wrapper img { width: 100%; height: 100%; object-fit: cover; }

.card-content { padding: 20px; text-align: start; flex-grow: 1; }
.post-card-title { font-size: 1.1rem; font-weight: 700; color: #fff; margin-bottom: 10px; line-height: 1.4; text-align: start; }
.post-card-snippet { color: var(--text-secondary); font-size: 0.85rem; line-height: 1.5; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; }

.post-single-container { max-width: 850px; margin: 0 auto; width: 100%; }
.post-content-body {
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    padding: 25px;
    border-radius: 20px;
    border: 1px solid var(--glass-border);
    box-sizing: border-box;
    overflow-wrap: break-word;
}
.post-content-body h1 { font-size: 1.6rem; line-height: 1.3; margin-bottom: 20px; text-align: start; }
.post-body-text { line-height: 1.7; font-size: 1rem; color: #cbd5e1; text-align: start; }
.post-body-text img { max-width: 100% !important; height: auto !important; border-radius: 12px !important; margin: 20px 0 !important; }

@media (max-width: 600px) {
    .main-container { margin-top: 100px; width: 94%; }
    .post-content-body { padding: 20px; }
    .post-content-body h1 { font-size: 1.4rem; }
    .logo { font-size: 1.3rem; }
    .posts-grid { grid-template-columns: 1fr; }
}

footer { background: rgba(5, 11, 20, 0.9); padding: 40px 20px; border-top: 1px solid var(--glass-border); text-align: center; }
.footer-links { display: flex; justify-content: center; gap: 15px; margin-bottom: 15px; flex-wrap: wrap; }
.footer-links a { color: var(--text-secondary); text-decoration: none; font-size: 0.85rem; }

#post-fetch-config { display: none; }

body.script:
    //
        function loadPostsByLabel(label, targetElementId) {
            var blogUrl = window.location.origin;
            var script = document.createElement('script');
            script.src = blogUrl + '/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json-in-script&callback=displayPosts';
            document.head.appendChild(script);

            window.displayPosts = function(json) {
                var postsContainer = document.getElementById(targetElementId);
                if (!postsContainer) return;
                postsContainer.innerHTML = '';

                if (json.feed && json.feed.entry && json.feed.entry.length > 0) {
                    json.feed.entry.forEach(function(entry) {
                        var postUrl = '';
                        for (var i = 0; i < entry.link.length; i++) {
                            if (entry.link[i].rel == 'alternate') {
                                postUrl = entry.link[i].href;
                                break;
                            }
                        }
                        var rawTitle = entry.title.$t || '';
                        var postTitle = rawTitle.split('{')[0].split('<')[0].trim();
                        if (postTitle === '') postTitle = 'مشاركة بدون عنوان';

                        var postImage = '';
                        if (entry.media$thumbnail) {
                            postImage = entry.media$thumbnail.url.replace('s72-c', 's1600');
                        } else if (entry.content && entry.content.$t.match(/<img[^>]+src="([^">]+)"/)) {
                            postImage = entry.content.$t.match(/<img[^>]+src="([^">]+)"/)[1];
                        }

                        var rawText = entry.summary ? entry.summary.$t : (entry.content ? entry.content.$t : '');
                        var cleanText = rawText.replace(/<(style|script)[^>]*>[\s\S]*?<\/\1>/gi, '');
                        cleanText = cleanText.replace(/<[^>]*>?/gm, '').trim();
                        var postSnippet = cleanText.substring(0, 100) + (cleanText.length > 100 ? '...' : '');

                        var imageHtml = postImage ? '<img src="' + postImage + '" loading="lazy"/>' : '<div class="card-icon-placeholder"><i class="fas fa-image"></i></div>';

                        var postCard = document.createElement('a');
                        postCard.href = postUrl;
                        postCard.className = 'post-card';
                        postCard.innerHTML = '<div class="card-image-wrapper">' + imageHtml + '</div>' +
                                             '<div class="card-content">' +
                                             '<h2 class="post-card-title">' + postTitle + '</h2>' +
                                             '<div class="post-card-snippet">' + postSnippet + '</div>' +
                                             '</div>';
                        postsContainer.appendChild(postCard);
                    });
                } else {
                    postsContainer.innerHTML = '<div style="grid-column: 1/-1; text-align: center; padding: 40px;">' +
                                             '<p style="color: var(--text-secondary); margin-bottom: 10px;">لا توجد مشاركات مرتبطة بهذا التصنيف حالياً.</p>' +
                                             '<p style="font-size: 0.8rem; color: #555;">التصنيف المطلوب: <b>' + label + '</b></p></div>';
                }
            };
        }

        function initializeStaticPagePosts() {
            var postsContainerId = 'static-page-posts-grid';
            var targetContainer = document.getElementById(postsContainerId);
            if (!targetContainer) return;

            var configEl = document.getElementById('post-fetch-config');
            var labelToFetch = '';

            if (configEl && configEl.getAttribute('data-label')) {
                labelToFetch = configEl.getAttribute('data-label');
            } else {
                labelToFetch = document.title.split(' : ')[0].split(' | ')[0].trim();
            }

            if (labelToFetch) {
                loadPostsByLabel(labelToFetch, postsContainerId
);
            }
        }

        function cleanupSnippets() {
            var snippets = document.querySelectorAll('.post-card-snippet');
            snippets.forEach(function(snippet) {
                var text = snippet.textContent;
                // Enhanced regex to catch CSS blocks and selectors even if partially cut off
                var cleanText = text.replace(/\{[\s\S]*?\}/g, ''); // Remove anything between { }
                cleanText = cleanText.replace(/[.#]?[a-z0-9_-]+\s*\{/gi, ''); // Remove selectors before {
                cleanText = cleanText.replace(/\.[a-z0-9_-]+|#[a-z0-9_-]+|property:\s*[^;]+;/gi, ''); // Remove class/id/props
                cleanText = cleanText.replace(/[a-z-]+\s*:\s*[^;{}]+;?/gi, ''); // Remove any key:value;
                cleanText = cleanText.replace(/[}{}:;]/g, ''); // Remove stray characters

                cleanText = cleanText.trim();
                if (cleanText !== text && cleanText !== "") {
                    snippet.textContent = cleanText;
                }
            });
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', function() {
                initializeStaticPagePosts();
                cleanupSnippets();
            });
        } else {
            initializeStaticPagePosts();
            cleanupSnippets();
        }
    //
